def add_reciprocal_link(path: Path, link_url: str, sentence: str) -> None:
    text = path.read_text(encoding="utf-8")
    if link_url in text:
        return
    match = re.search(r'(<p class="article-opening">.*?</p>)', text, flags=re.S)
    if not match:
        raise RuntimeError(f"Could not find opening paragraph in {path}")
    text = text[: match.end()] + sentence + text[match.end() :]
    path.write_text(text, encoding="utf-8", newline="\n")


def main() -> None:
    for item in ARTICLES:
        document = base.page(
            item["url"],
            item["seo"],
            item["title"],
            item["description"],
            item["deck"],
            item["department"],
            item["topic"],
            item["hero"],
            item["alt"],
            item["body"],
            "BlogPosting",
            item["words"],
            item["keywords"],
        )
        destination = ROOT / item["url"].strip("/") / "index.html"
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_text(document, encoding="utf-8", newline="\n")
        print("Built", destination.relative_to(ROOT))

    catalogue_path = ROOT / "content" / "articles.json"
    current = json.loads(catalogue_path.read_text(encoding="utf-8"))
    additions = []
    for item in ARTICLES:
        additions.append(
            {
                "title": html.unescape(item["title"]),
                "seoTitle": html.unescape(item["seo"]),
                "department": item["department"].lower(),
                "topic": item["topic"].lower().replace(" ", "-"),
                "published": PUBLISHED,
                "readingMinutes": round(item["words"] / 195),
                "readingWordsPerMinute": 195,
                "url": item["url"],
                "excerpt": html.unescape(item["deck"]),
                "metaDescription": item["description"],
                "image": {
                    "webp": f'{item["hero"]}.webp',
                    "fallback": f'{item["hero"]}.jpg',
                    "alt": item["alt"],
                    "width": 1536,
                    "height": 1024,
                },
                "articleSection": item["topic"],
                "breadcrumbTopic": True,
            }
        )
    urls = {item["url"] for item in additions}
    catalogue_path.write_text(
        json.dumps(additions + [item for item in current if item["url"] not in urls], ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
        newline="\n",
    )

    add_reciprocal_link(
        ROOT / "blogs/beauty/dragonfly-nails/index.html",
        EYELINER_URL,
        '<p>For another precise eye-level detail, our <a href="/blogs/beauty/eyeliner-stickers/">eyeliner sticker guide</a> covers shape, application, wear and a quieter everyday finish.</p>',
    )
    add_reciprocal_link(
        ROOT / "blogs/beauty/perfume-wardrobe-by-mood/index.html",
        TOMATO_URL,
        '<p>For the green mood in full, our <a href="/blogs/beauty/tomato-leaf-perfume-guide/">tomato leaf perfume guide</a> explains the vine accord, testing, layering and the drydowns that last beyond its sharp opening.</p>',
    )
    add_reciprocal_link(
        ROOT / "blogs/home/most-beautiful-kitchen-colour-combinations/index.html",
        HOOD_URL,
        '<p>Colour works best when the architecture is resolved first. Our <a href="/blogs/home/arched-range-hood-ideas/">arched range hood guide</a> covers proportion, ventilation and finishes for both compact and large kitchens.</p>',
    )
    add_reciprocal_link(
        ROOT / "blogs/fashion/how-to-wear-colour-again/index.html",
        TURQUOISE_URL,
        '<p>For one precise route back into colour, our <a href="/blogs/fashion/how-to-wear-turquoise-accessories/">turquoise accessories guide</a> pairs the shade with chocolate, charcoal, camel, oxblood and dark denim.</p>',
    )


if __name__ == "__main__":
    main()
